private const val RESERVATIONS_COLLECTION = "reservations"

/**
 * Shows the current entrant's active reservations (US 01.06.01) and past
 * reservations (US 01.06.02), and lets them cancel an active one (US 01.07.01).
 *
 * @param navController used to go back.
 * @param entrantId device user id; defaults to this device.
 */

/**
 * Documentation generated by Gemini
 * Screen listing active and historical reservations for the current entrant.
 *
 * @param navController Navigation controller for routing back to profile or home.
 */
@Composable
fun ReservationScreen(
    navController: NavController,
    entrantId: String? = null,
) {
    val context = LocalContext.current
    val resolvedEntrantId = entrantId ?: remember(context) { DeviceIdentity.getDeviceId(context) }

    var reservations by remember { mutableStateOf<List<Reservation>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var errorMessage by remember { mutableStateOf<String?>(null) }
    var cancellingId by remember { mutableStateOf<String?>(null) }
    var campsiteNames by remember { mutableStateOf<Map<String, String>>(emptyMap()) }

    DisposableEffect(resolvedEntrantId) {
        val listener = FirebaseFirestore.getInstance()
            .collection(RESERVATIONS_COLLECTION)
            .whereEqualTo("entrantId", resolvedEntrantId)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    errorMessage = error.message
                    isLoading = false
                    return@addSnapshotListener
                }
                errorMessage = null
                val list = snapshot?.documents?.mapNotNull { doc ->
                    runCatching { doc.toObject(Reservation::class.java) }.getOrNull()
                }.orEmpty()
                reservations = list
                isLoading = false

                val missingIds = list.map { it.campsiteId }.filter { it.isNotBlank() }.distinct()
                    .filter { it !in campsiteNames }
                missingIds.forEach { id ->
                    FirebaseFirestore.getInstance().collection("campsites").document(id).get()
                        .addOnSuccessListener { campDoc ->
                            val name = campDoc.toObject(Campsite::class.java)?.name ?: id
                            campsiteNames = campsiteNames + (id to name)
                        }
                }
            }
        onDispose { listener.remove() }
    }

    val active = reservations.filter { it.isActive() }
    val past = reservations.filter { it.isPast() }
    val dateFormat = remember { SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()) }

    fun cancelReservation(reservation: Reservation) {
        if (cancellingId != null) return
        cancellingId = reservation.reservationId
        errorMessage = null
        FirebaseFirestore.getInstance()
            .collection(RESERVATIONS_COLLECTION)
            .document(reservation.reservationId)
            .update(
                mapOf(
                    "status" to ReservationStatus.CANCELLED_BY_ENTRANT.name,
                    "updatedAt" to Date(),
                ),
            )
            .addOnSuccessListener { cancellingId = null }
            .addOnFailureListener {
                cancellingId = null
                errorMessage = it.message ?: "Could not cancel reservation"
            }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .padding(16.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Absolute.Left,
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton"),
            ) {
                Text("Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        errorMessage?.let {
            Text(it, color = MaterialTheme.colorScheme.error)
            Spacer(modifier = Modifier.height(8.dp))
        }

        when {
            isLoading -> {
                BoxCentered { CircularProgressIndicator() }
            }
            else -> {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .testTag("reservationsList"),
                ) {
                    item {
                        Text(
                            "Active reservations",
                            fontSize = 22.sp,
                            modifier = Modifier.testTag("activeReservationsHeader"),
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        if (active.isEmpty()) {
                            Text("No active reservations.", fontSize = 14.sp)
                        }
                    }
                    items(active, key = { it.reservationId }) { reservation ->
                        ReservationRow(
                            reservation = reservation,
                            campsiteName = campsiteNames[reservation.campsiteId]
                                ?: reservation.campsiteId,
                            dateFormat = dateFormat,
                            showCancel = true,
                            cancelling = cancellingId == reservation.reservationId,
                            onCancel = { cancelReservation(reservation) },
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                    }

                    item {
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            "Past reservations",
                            fontSize = 22.sp,
                            modifier = Modifier.testTag("pastReservationsHeader"),
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        if (past.isEmpty()) {
                            Text("No past reservations.", fontSize = 14.sp)
                        }
                    }
                    items(past, key = { it.reservationId }) { reservation ->
                        ReservationRow(
                            reservation = reservation,
                            campsiteName = campsiteNames[reservation.campsiteId]
                                ?: reservation.campsiteId,
                            dateFormat = dateFormat,
                            showCancel = false,
                            cancelling = false,
                            onCancel = {},
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                    }
                }
            }
        }
    }
}

@Composable
private fun BoxCentered(content: @Composable () -> Unit) {
    Column(
        modifier = Modifier.fillMaxSize(),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        content()
    }
}

@Composable
private fun ReservationRow(
    reservation: Reservation,
    campsiteName: String,
    dateFormat: SimpleDateFormat,
    showCancel: Boolean,
    cancelling: Boolean,
    onCancel: () -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("reservation_${reservation.reservationId}"),
    ) {
        Text(campsiteName, fontSize = 20.sp)
        Text("Status: ${reservation.status}", fontSize = 14.sp)
        val checkIn = reservation.checkInDate?.let { dateFormat.format(it) } ?: "—"
        val checkOut = reservation.checkOutDate?.let { dateFormat.format(it) } ?: "—"
        Text("Dates: $checkIn → $checkOut", fontSize = 14.sp)
        if (showCancel) {
            Spacer(modifier = Modifier.height(4.dp))
            Button(
                onClick = onCancel,
                enabled = !cancelling,
                shape = RectangleShape,
                modifier = Modifier.testTag("cancelReservation_${reservation.reservationId}"),
            ) {
                Text(if (cancelling) "Cancelling..." else "Cancel")
            }
        }
    }
}

